export const NEWS=[
  {v:45,title:'Kwiatki dla Werci 🌸',scene:'heather',items:['Na telefonie Werci w różowym kolorze rozkwitła wiosna: gałązka przy powitaniu kotków, kwiatek przy miesiącu i pod wybraną zakładką, kwiatki w kafelkach ustawień, w okienku wpisu, w Analizie i przy pustych ekranach.','🎯 Cele rosną jak łodyżka – na 100% zakwitają. Zamiast konfetti spadają płatki wiśni.','Kolor zmienisz w ⚙️ → 📱 Ten telefon → 🎨 Wygląd. Na telefonie Matiego nic się nie zmienia.']},
  {v:44,title:'Ustawienia w kafelkach ⚙️',scene:'duo',items:['⚙️ Ustawienia to teraz 6 kafelków: 🏦 Konta · 🗂️ Kategorie i drobne · 📱 Ten telefon · 🛡️ Bezpieczeństwo · 🤖 Automaty · 📖 Pomoc.','Stuknij kafelek – otworzy się tylko ta część. „‹ Ustawienia” (albo ⚙️) wraca do kafelków. Nic nie rozwija się samo.']},
  {v:43,title:'Każde ma swoje – część 2 👥',scene:'duo',items:['🔔 Na ekranie głównym, w „Na dziś”, w dymku kotków i w powiadomieniach każde widzi tylko swoje sprawy i wspólne: opłaty stałe, paski, raty, odsetki, koniec umowy, najem, „nie starczy na rachunki”.','👥 Czyje to jest, wynika z „👥 Dotyczy” w opłacie, a gdy puste – z konta. Płacisz swoją opłatę ze wspólnego konta? Ustaw „Dotyczy” na siebie.','📅 Wydatki roczne i 🔔 przypomnienia też mają „👥 Dotyczy” – np. OC Twojego auta albo fryzjer. Puste = wspólne, przypomina obojgu.','🤖 Sprawy techniczne (kopia danych, automat, limity IKE/IKZE) – tylko u Matiego.','W 📌 Stałe nadal widać wszystko – przełącznikiem Wszystkie · Mati · Wercia · Wspólne.']},
  {v:42,title:'Każde ma swoje 👥',scene:'duo',items:['👥 W 📌 Opłatach na górze: Wszystkie · Mati · Wercia · Wspólne – widać tylko opłaty, przychody i przelewy stałe wybranej osoby. Czyje są, wynika z konta, z którego idą; w edycji opłaty jest też „👥 Dotyczy”, gdy np. Twój telefon płaci konto wspólne.','🔒 Bailey i Ivo raz zapytają, czyj jest login – potem ten telefon zawsze podpisuje wpisy właściwą osobą i nie da się jej przestawić przypadkiem.','🙀 Wpis z konta drugiej osoby? Kotki zapytają, czy na pewno. „Tak, wiem” – do końca dnia nie pytają o to konto. Konta wspólne i przelewy na konto drugiej osoby – bez pytania.']},
  {v:41,title:'Szybciej i porządniej ⚡',scene:'ivoHappy',items:['⚡ Po zapisie ekran odświeża się raz zamiast dwa–trzy razy (potwierdzenie z serwera zmienia już tylko napis „zsynchronizowano”). Sprawdziliśmy też aplikację na 15 000 wpisów – działa płynnie.','🧹 Porządki w środku aplikacji: mniej starego kodu, który już nic nie robił. Wasze dane są nietknięte.']},
  {v:40,title:'Odsetki z kont 💰',scene:'coin',items:['💰 Przy koncie oszczędnościowym (i subkoncie) jest „💰 Oprocentowanie”: stawka, promocja (do kiedy i do jakiej kwoty), kiedy bank dopisuje odsetki i jak z podatkiem.','🧮 Odsetki liczę dzień po dniu od salda – wpłata z połowy miesiąca zarabia pół miesiąca. Z podatkiem Belki 19%, bez niego przy IKE, IKZE i OKI. Bank zagraniczny (np. Revolut)? „Rozliczam sam” – w marcu przypomnę, ile wpisać w PIT-38.','🔔 W dniu dopisania odsetek „Na dziś” pokaże gotową kwotę – „Wpisz” i ewentualnie popraw grosze z wyciągu. Odsetki to zysk, nie „odłożone”.','🎁 2 tygodnie przed końcem promocji przypomnę, żeby przenieść pieniądze. W Oszczędnościach nowa karta „Odsetki z kont”.']},
  {v:39,title:'Ciekawostki od kotków 🐾',scene:'lupa',items:['🐾 Gdy kotki ostrzegają (opłata po terminie, przekroczony plan, blisko limitu), pod dymkiem jest „Rozumiem, kociaki”. Uwaga znika do jutra na tym telefonie – chyba że coś się zmieni, np. dojdzie kolejna opłata po terminie.','📚 Zamiast uwagi – ciekawostka dnia o budżecie, oszczędzaniu i inwestowaniu. Jest ich 366, na każdy dzień roku inna (29 lutego – specjalna), na obu telefonach ta sama. Po południu kotki pokazują ją same.','🎄 W święta i urodziny – życzenia i nazwa dnia (doszły m.in. Wigilia, Mikołajki, 11 Listopada, 3 Maja, Dzień Dziecka i Dzień Oszczędzania).','💬 Dymki są wyraźniejsze: najpierw konkret z kwotą (pogrubiony), potem żart.']},
  {v:38,title:'Pewniejsza kopia i poprawki 🛠️',scene:'lupa',items:['💾 Kopia (z ⚙️ i z maila) zapisuje teraz wszystko: także ustawienia kaskady, schowane podpowiedzi, subkonto kopert rocznych, wpisaną inflację, limity IKE/IKZE, urodziny i zamknięcia miesięcy. Po wczytaniu aplikacja wraca dokładnie do stanu z kopii.','📅 Wydatki „co kwartał” i „co miesiąc” po zapłacie znowu wchodzą do planu w kolejnym terminie, a wpis przez ＋ podpowie „To ta opłata?”.','🔁 Wpis przeniesiony na inny miesiąc zachowuje wszystkie powiązania, a po usunięciu zawsze jest w „Ostatnio usunięte”. Wpis z konta w archiwum pokazuje to konto.','🔄 Nowa wersja aplikacji pobiera się w tle w całości i dopiero wtedy się włącza – słaby internet niczego nie popsuje. 🔍 🔔 ⚙️ stoją równo.']},
  {v:37,title:'Zamknięcie przed wypłatą 💧',scene:'lupa',items:['🗓️ Każde z Was ma własne zamknięcie miesiąca – dzień przed swoją wypłatą. Dzień wypłaty aplikacja zna sama z wpisanych pasków (koniec miesiąca, weekend → piątek). „Co było ponad plan” i „Plan” są wspólne.','💧 Kaskada liczy nadwyżkę dzień przed wypłatą – wtedy na koncie jest to, co naprawdę zostało. W środku miesiąca nie proponuje przelewu pieniędzy na zakupy, a nowej pensji nigdy nie liczy jako nadwyżki.','⚠️ Nowe w „Na dziś”: „nie starczy na rachunki” – gdy na koncie zabraknie na opłatę stałą przed terminem, z przyciskiem „Przelej”.','🔁 Stały przelew może iść też na konto wspólne albo do drugiej osoby. Powtarzający się przelew sam podpowiem.','🛟 Poduszka nie jest już pulą na cele. 📝 Plan po zamknięciu – ze średniej z 3 miesięcy. 🧾 Rejestr w dwóch linijkach. ⚖️ Salda wyrównujecie wszystkie naraz.']},
  {v:36,title:'Zamknięcie miesiąca 🗓️',scene:'lupa',items:['🗓️ W pierwszych dniach miesiąca na Budżecie i w „Na dziś” czeka „Zamknij wrzesień” – 5 kroków, ok. 10 minut: salda z bankiem, co było ponad plan, nadwyżka, plan na nowy miesiąc i cele.','🏦 Przy każdym koncie widać, kiedy ostatnio sprawdzaliście saldo z bankiem. „✓” – zgadza się, „⚖️” – wpisz saldo z banku.','👫 Kroki możecie podzielić – odhaczone widać na obu telefonach. 1. dnia miesiąca przypomnę powiadomieniem. Zawsze możecie zajrzeć: przycisk na dole Budżetu.']},
  {v:35,title:'Uczciwe porównania i krótszy Rejestr ⏳',scene:'lupa',items:['⏳ W trwającym miesiącu Analiza porównuje z poprzednim miesiącem do tego samego dnia (np. 1–25 października z 1–25 września), a nie z całym miesiącem – strzałki nie chwalą już za wcześnie.','📊 „Zmieściło się” i „wyraźnie mniej niż plan” pokażę po końcu miesiąca. W trakcie widać to, co już przekroczone albo poza planem.','🧾 Rejestr: wyszukiwarka i okres na górze, reszta filtrów pod przyciskiem „⚙️ Filtry”. Przy każdym dniu suma wydatków.']},
  {v:34,title:'Jeden rachunek – jeden wpis 📌',scene:'bell',items:['📌 Gdy wpiszesz przez ＋ rachunek, który jest w opłatach stałych (np. Netflix) albo w wydatkach rocznych (np. OC), zapytam: „To … z opłat stałych?” – jedno „Tak” i rachunek jest odhaczony, bez przypominania.','✓ Gdy odhaczasz opłatę, a ktoś już ją wpisał przez ＋, zaproponuję „Połącz z tym wpisem” zamiast drugiego wydatku. W 📌 Stałe i w „Na dziś” widać „💡 jest podobny wpis”.','📊 Budżet ostrzega, gdy plan pozycji jest niższy niż jej opłaty stałe (np. po podwyżce czynszu) – „Podnieś plan do opłat stałych”.']},
  {v:33,title:'Urodziny i ulga dla młodych 🎂',scene:'celebrate',items:['🎂 Bailey i Ivo zapytają o Twoją datę urodzenia (każde z Was na swoim telefonie). W dniu urodzin złożą Ci życzenia – w aplikacji i rano w powiadomieniu – a drugiej osobie przypomną o życzeniach. Datę zmienisz w ⚙️ → „Kto korzysta z tego telefonu?”.','🎓 Ulga dla młodych liczy się sama: do 26. urodzin pensja z umowy o pracę i zlecenia jest bez podatku (do 85 528 zł w roku, ze wszystkich umów razem). „Podpowiedz z brutto” i „z netto” to uwzględniają, ZUS i zdrowotna zostają bez zmian.','🎓 Miesiąc przed 26. urodzinami przypomnę w „Na dziś”, że wypłaty będą niższe – i o ile mniej więcej.']},
  {v:32,title:'Roczne i terminy, porządki 🧹',scene:'bell',items:['📅 Przypomnienia i wydatki roczne są teraz w jednej zakładce „Roczne i terminy” (📌 Stałe). Jeden przycisk „+ Dodaj” z gotowymi: OC, ubezpieczenie, przegląd, opony, szczepienie kotów. Z kwotą – odkładanie, bez – samo przypomnienie. Zawsze ok. 2 tygodnie przed terminem.','🏠 Najem: przy przychodzie stałym przypomnę o ryczałcie (z kwotą) i o PIT-28. 🧾 Od 1 marca przypomnienie o PIT dla każdego z Was.','💧 Kaskada nadwyżek zostawia 250 zł na koncie, mówi, ile zostało w planie do końca miesiąca, i nigdy nie proponuje PPK ani gotówki.','⚙️ Ustawienia w grupach. Wartości inwestycji aktualizujesz w jednym miejscu: „📈 Aktualizuj wartości” (albo robi to automat). Bez pliku do kalendarza i starych wpisów inwestycji.']},
  {v:31,title:'Lepsze planowanie 📝',scene:'papers',items:['📅 Wydatki roczne same wchodzą do planu w miesiącu płatności (np. OC w marcu) – i nie kopiują się na kolejny miesiąc. W Budżecie pod pozycją widać „📅 do planu doliczone”.','📊 Analiza → Rok → „Plan a rzeczywistość”: pozycje, które prawie co miesiąc przekraczają plan (albo są dużo poniżej), z przyciskiem „Ustaw … od listopada”.','🙈 Pozycje i całe kategorie można ukryć (⚙️ → Kategorie → stuknij pozycję). Znikają z Budżetu i z wpisywania, historia zostaje. Pozycji z wpisami nie da się już usunąć – tylko ukryć.']},
  {v:30,title:'Prawdziwe liczby 🐷',scene:'coin',items:['🐷 „Odłożone” to teraz tylko to, co naprawdę przelaliście na oszczędności i inwestycje (z PPK). Wzrost albo spadek kursów pokazuję osobno: „inwestycje zarobiły / straciły”. Tak samo w mailu i w podsumowaniu roku.','📊 W Budżecie, pod kafelkami, widać „Odłożone w tym miesiącu” i ile to z Waszego celu.','🛟 Jedna karta poduszki: liczę tylko konta oszczędnościowe – bez IKE, IKZE, PPK i inwestycji, których nie da się szybko wypłacić. Cele-koperty też już nie liczą IKE, IKZE i PPK.','💑 Mati ↔ Wercia: wydatki według tego, czyje było konto – z konta wspólnego trafiają do „Wspólne”.']},
  {v:29,title:'Pensje prościej 💼',scene:'calc',items:['🧮 Nie masz jeszcze paska? W pasku stuknij „Podpowiedz z netto” i wpisz, ile wpłynęło na konto – brutto, ZUS, zdrowotną, podatek i PPK policzę orientacyjnie (PPK możesz wyłączyć w danym miesiącu).','✂️ Przy źródle dochodu zapytam, co jest potrącane od razu z pensji (np. ubezpieczenie grupowe, Multisport). Potrącenia wpisują się same w każdym nowym pasku i trafiają do budżetu.','➕ W 💼 Pensje jest „+ Inny przychód” i lista przychodów spoza pasków (sprzedaż rzeczy, premia, zwrot PIT, najem).','👯 Gdy ta sama pensja miałaby się wpisać dwa razy (z paska i z 📌 Stałe), aplikacja zapyta.']},
  {v:28,title:'Pewniej i szybciej 🛡️',scene:'lupa',items:['👯 Gdy wpisujecie ten sam paragon drugi raz (ta sama kwota, dzień i sklep), aplikacja zapyta: „Taki wpis już jest – zapisać mimo to?”.','💾 Co miesiąc, po wysłaniu kopii mailem, robot wczytuje ją na próbę i sprawdza wszystkie wpisy i salda. Gdyby coś było nie tak, dostaniesz maila od GitHuba.','🧾 W styczniu przypomnę, żeby zaktualizować zasady pensji (ZUS, progi) na nowy rok.','⚡ Aplikacja liczy szybciej przy wielu latach danych – sprawdzone na 18 000 wpisów (10 lat).']},
  {v:27,title:'Drobne szlify wyglądu 🎨',scene:'happy',items:['Przyciski „+ …”, „+ / −” przy kwocie i „Podziel paragon” są teraz w kolorze Twojego telefonu.','Stałe przelewy: „Przelane 1 z 1”. Pusta zakładka „🔻 My winni” nie pokazuje już karty z zerami. Analiza → Rok: przy „Zostało w roku” średnia miesięczna.']},
  {v:26,title:'Szybciej i pewniej ✍️',scene:'papers',items:['✍️ Przy notatce pojawiają się podpowiedzi – Wasze najczęstsze sklepy i miejsca. Jedno stuknięcie wpisuje nazwę (i podpowiada pozycję). Te same nazwy = dokładniejsze „🏪 Gdzie wydajemy”.','📷 Gdy zakup ma gwarancję, w okienku jest „Dołącz zdjęcie paragonu”. Na liście gwarancji widać 📷 przy zakupach ze zdjęciem.','🙈 Przytrzymaj nazwę miesiąca w nagłówku – tryb dyskretny włącza się i wyłącza.','🤖 Robot sprawdza teraz także obliczenia: pensje, obligacje, raty, salda.']},
  {v:25,title:'Zdjęcia paragonów 📷',scene:'envelope',items:['W okienku wpisu na dole: „📷 Zdjęcie paragonu” – zrób zdjęcie albo wybierz z galerii (do 3 przy jednym wpisie). Przyda się przy reklamacji i gwarancji.','Telefon sam zmniejsza zdjęcie do ok. 100–180 KB, paragon dalej jest czytelny. Zdjęcia leżą w Waszej bazie Firebase w darmowym limicie (1 GB = kilka tysięcy zdjęć) – nic nie trzeba płacić.','Stuknij miniaturkę, żeby powiększyć albo zapisać w telefonie. W Rejestrze wpis ze zdjęciem ma 📷.','⚙️ → Kopia danych: ile miejsca zajmują zdjęcia i „📷 Pobierz kopię ze zdjęciami” (comiesięczny mail z kopią ich nie zawiera).']},
  {v:24,title:'Umowy, koszt roczny i sklepy 🏪',scene:'calc',items:['📄 Opłata stała → „Umowa do…”: 2 miesiące przed końcem umowy (internet, telefon, OC) przypomnę w „Na dziś”, żeby porównać oferty albo negocjować. „Załatwione” chowa przypomnienie.','📆 W 📌 Stałe widać, ile opłaty stałe kosztują w roku – osobno subskrypcje i wydatki roczne.','🏪 Analiza (Pełna) → „Gdzie wydajemy”: sklepy i miejsca z notatek – ile, ile razy i średnio za jednym razem, w miesiącu i w roku.']},
  {v:23,title:'Ostatnio usunięte i tryb dyskretny 🙈',scene:'box',items:['🗑️ ⚙️ → „Ostatnio usunięte”: wpisy usunięte w ostatnich 60 dniach, z przyciskiem „↩️ Przywróć” (wraca razem ze zwrotami, PPK i odsetkami).','🙈 ⚙️ → Wygląd → „Ukryte”: wszystkie kwoty jako „•••”, gdy pokazujecie komuś telefon. Pasek „Pokaż kwoty” na górze wyłącza tryb.','🚫 Podwójne stuknięcie nie przybliża już ekranu. Przybliżyć można dwoma palcami.']},
  {v:22,title:'Porządki po przeglądzie ✨',scene:'lupa',items:['Analiza → Rok: średnie „/mies.” liczą się od pierwszego miesiąca z wpisami (wcześniej dzieliły przez wszystkie miesiące od stycznia i wychodziły za niskie).','Kwoty od 1000 zł zawsze z odstępem („5 449,18 zł”), kolor telefonu także w okienku nowego wpisu, jednakowe przyciski propozycji, „+ …” zawsze wielką literą.','Na wąskim telefonie z dużym tekstem: tabela „Miesiąc po miesiącu”, filtr „▲ Ponad plan” i „+ Przelew” mieszczą się w jednej linijce; napisy w „Przepływie pieniędzy” nie nachodzą na siebie.','💰 Majątek: „👛 Konta” → „🏦 Salda / 🔻 My winni / 🔺 Nam winni”. Nowy wpis na telefonie bez historii ustawia konto osoby telefonu.','Bailey: zamknięte oko na brązowej łacie jest teraz widoczne. 🤖 Każdą zmianę aplikacji sprawdza najpierw robot na GitHubie.']},
  {v:21,title:'Raty liczą się same 🔻',scene:'calc',items:['👛 Konta: stan kont nie jest już pomniejszany o zobowiązania. Obok widać osobno „🔻 do spłaty” i „🔺 pożyczone innym”.','Wpisz przy zobowiązaniu oprocentowanie nominalne (nie RRSO) i wybierz raty równe albo malejące – aplikacja policzy ratę, ile z niej to odsetki, koniec spłaty i odsetki do końca.','„+ Rata” sama wpisuje podpowiedzianą kwotę – zmienisz ją, jeśli bank pobrał inną. Bez oprocentowania dzieli to, co zostało, na równe części do końca.','W dniu raty 🔔 „Na dziś” przypomni: „Rata: … – ok. 803,44 zł”.']},
  {v:20,title:'Odkładanie na spłatę pożyczki 💰',scene:'coin',items:['🔻 My winni → Edytuj → „💰 Zbieram na spłatę całości na koncie”: wybierz konto, na które odkładasz. Na jedno konto możesz zbierać na kilka pożyczek.','Na karcie pożyczki widać „odłożone” i pasek. „💰 Odłóż” otwiera przelew, a w przelewie wpisujesz, ile idzie na którą pożyczkę. Stały przelew w 📌 Stałe też możesz przypisać do pożyczki.','Potrzebujesz pieniędzy na życie? „↑ Weź z odłożonych” – licznik spadnie i nic się nie rozjedzie. Strażnik ostrzeże, gdy na koncie jest mniej, niż odłożono.','„✅ Spłać całość”: spłata kapitału nie liczy się w Budżecie (to oddanie pożyczonych pieniędzy), a odsetki trafiają do Budżetu z dopiskiem „Odsetki od spłaty pożyczki”.']},
  {v:19,title:'Podsumowanie roku 🖨️',scene:'papers',items:['📈 Analiza → Rok → „🖨️ Podsumowanie roku”: cały rok na jednej stronie – przychody, wydatki, miesiąc po miesiącu, kategorie, majątek, IKE/IKZE/PPK i ulgi do PIT.','Przycisk „Zapisz jako PDF / drukuj” zapisze ją jako plik albo wydrukuje.','1 stycznia automat wyśle Wam obojgu podsumowanie poprzedniego roku mailem.','W Rejestrze znów widać wszystkie filtry (zakres, rodzaj, osoba, konto, kategoria).']},
  {v:18,title:'Wersja demonstracyjna 🧪',scene:'wink',items:['Chcesz komuś pokazać aplikację? ⚙️ → „🧪 Pokaż komuś aplikację” → 📤 Wyślij link.','Demo ma przykładowe dane, zapyta o imię gościa i nie widzi niczego z Waszego budżetu. Zmiany zostają tylko w jego przeglądarce.','📖 ⚙️ → „Co nowego i jak to działa”: lista wszystkich funkcji – stuknij, a zobaczysz, do czego służą i jak ich używać. Lupa 🔍 też je znajdzie.','Nowe „Pierwsze kroki” z kotkami: ⚙️ → „Pokaż pierwsze kroki”.']},
  {v:17,title:'Wygodniej i ładniej 🎨',scene:'duo',items:['Cztery zakładki: Budżet · Rejestr · Stałe · 💰 Majątek (Oszczędności i Konta razem). Analiza otwiera się z Budżetu.','🔍 w nagłówku szuka wszędzie: wpisy (też po kwocie), pozycje, konta, instrumenty.','Przytrzymaj wpis w Rejestrze: 📋 Duplikuj, ↩️ Zwrot, 🗑️ Usuń. Przesuń palcem w bok, żeby zmienić miesiąc.','„Zapisz” jest zawsze na dole okienka, a „Zapisz i dodaj kolejny” przyspiesza wpisywanie paragonów.','Budżet jest krótszy: puste pozycje chowają się pod „＋ pustych pozycji”, puste kategorie są na dole.','⚙️ → 🎨 Wygląd: kolor (Wercia różowy, Mati miętowy) i większy tekst A+ / A++.','Nowe „Pierwsze kroki” z kotkami pokazują wszystko po kolei: ⚙️ → „Pokaż pierwsze kroki”.']},
  {v:16,title:'Inwestycje liczą się same 🏛️',scene:'duo',items:['🏛️ Obligacje EDO, COI, ROS i ROD: każdy rok liczę z inflacji GUS sprzed 2 miesięcy + marża. Przycisk „📅 Oprocentowanie” pokazuje każdy rok i pozwala go poprawić.','Przy nowej obligacji podpowiadam oprocentowanie serii, która jest w sprzedaży w tym miesiącu.','🧺 Fundusze PPK i TFI: wybierasz fundusz z listy i wpisujesz liczbę jednostek, a automat codziennie pobiera wartość jednostki.','📈 Na koniec miesiąca automat sam zapisuje wycenę kont z instrumentami (wpis „(automat)”, można go usunąć w Rejestrze).','📌 Płacisz coś co miesiąc, a nie ma tego w Stałych? Po 3 miesiącach zapytam, czy to dodać.']},
  {v:15,title:'Wygoda na co dzień 🗣️',scene:'wink',items:['„Hej Siri, wydatek” – Siri zapyta o kwotę i notatkę, a okienko otworzy się wypełnione (⚙️ → „Siri i skróty” → Jak to ustawić).','🛡️ Przy zakupie od 300 zł zapytam o gwarancję i przypomnę miesiąc przed jej końcem. Lista gwarancji jest w 📌 Stałe → 🔔 Przyp.','🧾 Wydatek oznaczysz „do ulgi w PIT” (z objaśnieniem ulgi). Zestawienie osobno dla Matiego i Werci jest w 💼 Pensje → Rok.','🕑 Przy każdym wpisie widać, kto go dodał lub zmienił, a w ⚙️ jest lista ostatnich zmian.']},
  {v:14,title:'Maile od automatu 📧',scene:'envelope',items:['💾 W pierwszą niedzielę miesiąca Mati dostaje mailem kopię zapasową (mały plik .json.gz). Wczytasz ją w ⚙️ → „Wczytaj kopię”.','📊 1. dnia miesiąca oboje dostajecie pastelowe podsumowanie poprzedniego miesiąca: plan a wydatki, co przekroczone, ile odłożyliście.','Adresy to te, którymi logujecie się do aplikacji.']},
  {v:13,title:'Prawdziwe powiadomienia 🔔',scene:'bell',items:['W ⚙️ → „🔔 Powiadomienia” włączysz powiadomienia na swoim telefonie: rano ok. 7:30 „Na dziś” (tylko gdy coś czeka), o 20:00 przypomnienie, gdy dziś nic nie wpisano.','Wspólne sprawy przychodzą do Was obojga, osobiste (pasek pensji, IKZE) tylko do właściciela. Z powiadomieniami okienka nie wyskakują już same – dzwonek 🔔 zostaje.','🧹 Strażnik porządku pilnuje duplikatów, wpisów bez pozycji i ujemnych sald. „To nie błąd” ukrywa podpowiedź na stałe.','Pilne sprawy widać w małym pasku na górze Budżetu. Automat sam pilnuje, żeby GitHub go nie wyłączył.']},
  {v:12,title:'Okno „Na dziś” 🔔',scene:'duo',items:['Dzwonek 🔔 u góry zbiera wszystko, co czeka: opłaty, paski pensji, wydatki roczne, auto, pożyczki, obligacje, limity i kopię.','Pierwszy raz każdego dnia okno otworzy się samo – tylko wtedy, gdy coś czeka.','Po 20:00, gdy danego dnia nic nie wpisano, przypomnimy o wydatkach. Wszystko w aplikacji, bez kalendarza.']},
  {v:11,title:'Nowa Analiza 📊',scene:'lupa',items:['Przełącznik „Podstawowa | Pełna” – każdy telefon pamięta swój.','Podsumowanie miesiąca z kotkami: co się zmieściło, co przekroczone, co poza planem.','Mati ↔ Wercia, przepływ pieniędzy (Sankey), majątek i kategorie przez 12 miesięcy.','„Wasza inflacja”: kategorie rok do roku obok inflacji GUS.','W widoku „Rok”: eksport do Excela i 🎁 Money Wrapped – Wasz rok opowiedziany przez Bailey i Ivo.']},
  {v:10,title:'Planowanie 📝',scene:'calc',items:['Budżet podpowiada plan: średnia z 3 miesięcy w pustym polu i przycisk „Wypełnij średnimi”.','🏷️ Projekty: stałe (koty, mieszkanie) liczą się do budżetu, jednorazowe (wyjazd, remont) są osobno. Opcjonalny budżet z paskiem.','🚗 Pojazd: przy paliwie wpisujesz litry i licznik – spalanie, cena litra i koszt kilometra liczą się same.','📌 Stałe → „🔔 Przyp.”: OC, przegląd, opony, serwis co X km, szczepienia kotów.','Analiza pokazuje, gdzie wydaliście nietypowo dużo, a Oszczędności – kaskadę nadwyżek do odłożenia.']},
  {v:9,title:'Zobowiązania i należności 🔻🔺',scene:'lupa',items:['W 👛 Konta są teraz zakładki „🔻 My winni” i „🔺 Nam winni”.','Kredyty, raty i pożyczki: od kogo, kto spłaca, warunki, pasek spłaty i szacowany koniec. Przy kredycie w banku wpisujesz „pozostało”, prywatna pożyczka liczy się sama.','Rata to dalej wydatek w Budżecie – w okienku wybierasz tylko, które zobowiązanie spłaca.','Pożyczki dla innych z terminem zwrotu i częściowymi zwrotami. Stare „Udzielone pożyczki” przeniesiesz jednym przyciskiem.']},
  {v:8,title:'Oszczędności i inwestycje 📈',scene:'coin',items:['„🐷 Odłóż” w Oszczędnościach i stałe przelewy na oszczędności w 📌 Stałe.','„📊 Instrumenty” przy kontach inwestycyjnych: ETF, akcje, obligacje (EDO, COI, TOS…), złoto, krypto, lokaty – zysk z ceny i z kursu, kwota na rękę po Belce, termin wykupu.','„📈 Aktualizuj wartości” – wszystkie konta inwestycyjne na jednym ekranie.','Limity IKE, IKZE i OKI, wykres „wpłacone a wartość”, FIRE i poduszka.','📌 Stałe → „📅 Roczne”: wydatki raz w roku z kopertami na wspólnym subkoncie – aplikacja liczy, ile odkładać co miesiąc.']},
  {v:7,title:'Pensje 💼',scene:'papers',items:['W 📌 Stałe → „💼 Pensje” dodasz źródła dochodu Matiego i Werci: umowę o pracę, zlecenie, dzieło albo kontrakt / JDG.','Co miesiąc wpisujesz pasek: składniki, ZUS, zdrowotną, podatek, PPK i potrącenia. „Podpowiedz z brutto” liczy szacunek, a aplikacja sprawdza, czy rachunek się zgadza.','Netto, potrącenia (np. Multisport) i PPK same trafiają do budżetu. ZUS i podatek widać tylko w pasku.','Widok „Rok” podsumowuje wszystko do sprawdzenia PIT-11.']},
  {v:6,title:'Waluty 🌍',scene:'happy',items:['Każde konto może mieć swoją walutę (⚙️ → Konta → Edytuj → Waluta) – euro, dolar, funt i każda inna z tabeli NBP. Kwoty nie są przeliczane na złote.','Wymiana walut to przelew z dwiema kwotami – kurs policzę sam i dopiszę do notatki.','Płacisz kartą złotówkową za granicą? Wpisz kwotę w zł, stuknij „🌍 Płatność w obcej walucie” i podaj kwotę w walucie.','W budżecie zobaczysz np. „wydano 820 zł + 45 €” – plan zostaje w złotych.']},
  {v:5,title:'Drobne 🪙',scene:'coin',items:['W ⚙️ → „🪙 Drobne” ustawisz regułę: z którego konta, na które, zaokrąglenie do 5 albo 10 zł i mnożnik.','Przy wydatku z tego konta pojawi się złota moneta z kwotą drobnych. Odznacz ją, gdy bank ich nie liczy (np. BLIK).','Drobne widać pod wydatkiem w Rejestrze i w Oszczędnościach.']},
  {v:4,title:'Poznajcie nas! 🐾',scene:'happy',items:['Bailey i Ivo zamieszkali w aplikacji – witają na Budżecie i podpowiadają, co warto zrobić.','Pamiętamy o urodzinach, świętach i Dniu Kota.','W ⚙️ → „Bailey i Ivo” ustawisz, ile nas ma być: dużo, mało albo wcale.']},
];
export const NEWS_V=NEWS[0].v;
/* 📖 guide to every feature (⚙️ → „Co nowego i jak to działa”): sections → items {i:icon, t:title, s:short, w:what it is for, h:[how, step by step], v?:version it came with} */
export const HELP=[
 {s:'✍️ Wpisywanie',items:[
  {i:'➕',t:'Dodawanie wydatku lub przychodu',s:'kwadratowy ＋ w prawym dolnym rogu',w:'Każdy wydatek, przychód albo przelew między kontami wpisujesz w jednym okienku. Z tych wpisów liczy się cały budżet, salda kont i Analiza.',h:['Stuknij ＋.','Wybierz u góry: Wydatek, Przychód albo Przelew.','Wpisz kwotę (przyciskami + i − dodasz lub odejmiesz kolejne kwoty, np. dwa paragony).','Stuknij „Pozycja budżetu” i wybierz ją z listy albo wpisz kilka liter. Po notatce (np. „Biedronka”) podpowiem pozycję sam.','Sprawdź konto i datę, potem „Zapisz”.']},
  {i:'✍️',t:'Podpowiedzi notatki',s:'najczęstsze sklepy',w:'Gdy stukasz w notatkę albo zaczynasz pisać, pod polem pojawiają się Wasze najczęstsze notatki z ostatniego roku (np. Biedronka, Orlen). Stuknięcie wpisuje nazwę i podpowiada pozycję budżetu.',h:['Okienko wpisu → stuknij „Notatka” albo wpisz pierwsze litery → stuknij podpowiedź.'],v:26},
  {i:'⏩',t:'Zapisz i dodaj kolejny',s:'kilka paragonów pod rząd',w:'Gdy wpisujesz kilka rzeczy naraz, nie musisz za każdym razem otwierać okienka od nowa.',h:['W okienku na dole jest przycisk „Zapisz i dodaj kolejny ›”.','Po zapisaniu okienko otworzy się puste, z tym samym kontem i datą.'],v:17},
  {i:'👯',t:'Podwójny wpis',s:'ten sam paragon dwa razy',w:'Gdy zapisujesz wpis z tą samą kwotą, w tym samym lub sąsiednim dniu i z tą samą notatką albo pozycją co istniejący, aplikacja pyta, czy to nie ten sam zakup (np. gdy oboje wpisaliście jeden paragon).',h:['„Nie zapisuj” – okienko zostaje, nic się nie zapisuje.','„Zapisz mimo to” – gdy to naprawdę drugi taki sam zakup.'],v:28},
  {i:'✂️',t:'Dzielenie paragonu',s:'jeden paragon – kilka pozycji',w:'Jeden paragon z Biedronki może zawierać jedzenie, chemię i karmę dla kotów. Każda część trafi do swojej pozycji budżetu.',h:['W okienku stuknij „✂️ Podziel paragon na kilka pozycji”.','Dodaj wiersze z kwotą i pozycją. Reszta kwoty zostaje w pierwszej pozycji.']},
  {i:'↩️',t:'Zwrot',s:'oddali pieniądze za zakup',w:'Zwrot zmniejsza wydatek w tej samej pozycji (nie liczy się jako przychód), więc budżet pokazuje prawdę.',h:['Otwórz wydatek w Rejestrze i stuknij „↩️ Oznacz zwrot” (albo przytrzymaj wpis → Zwrot).','Wpisz, ile wróciło, i datę.']},
  {i:'🌍',t:'Obce waluty',s:'płatność kartą za granicą, konta walutowe',w:'Konto może być w euro czy dolarach – kwoty nigdy się nie przeliczają same. Płacąc kartą złotówkową za granicą, zapiszesz też kwotę w walucie i kurs.',h:['Przy wydatku stuknij „🌍 Płatność w obcej walucie” i wpisz kwotę w walucie.','Przelew między kontami w różnych walutach zapyta, ile wpłynęło na drugie konto.']},
  {i:'🪙',t:'Drobne',s:'zaokrąglanie jak w Revolucie',w:'Każdy wydatek z konta z regułą zaokrągla się w górę, a różnica idzie na oszczędności. Małe kwoty, a po roku robi się z tego sporo.',h:['⚙️ → „🪙 Drobne” → „+ reguła”: wybierz konto, na które idą drobne, i krok (5 lub 10 zł).','Przy wydatku z tego konta widać złotą monetę – stuknij ją, jeśli tym razem nie chcesz odkładać.']},
  {i:'📷',t:'Zdjęcie paragonu',s:'paragon, gwarancja, faktura',w:'Do wpisu możesz dołączyć do 3 zdjęć (paragon, karta gwarancyjna, faktura). Telefon sam je zmniejsza, więc mieszczą się w darmowym miejscu Firebase. Zdjęcie wczytuje się dopiero, gdy otworzysz wpis.',h:['Okienko wpisu → na dole „📷 Zdjęcie paragonu” → aparat albo galeria.','Stuknij miniaturkę – powiększenie i „💾 Zapisz w telefonie”; × usuwa zdjęcie (po „Zapisz”).','⚙️ → Kopia danych → „📷 Pobierz kopię ze zdjęciami” – raz na jakiś czas, bo mail z kopią nie zawiera zdjęć.'],v:25},
  {i:'🛡️',t:'Gwarancja',s:'przypomnienie przed końcem gwarancji',w:'Przy droższym zakupie (od 300 zł) zapisujesz, jak długo trwa gwarancja. Miesiąc przed końcem przypomnę – to ostatni moment na reklamację.',h:['W okienku wydatku od 300 zł pojawi się „🛡️ Gwarancja” – wybierz 1, 2, 3, 5 lat albo datę.','Lista wszystkich gwarancji: 📌 Stałe → 📅 Roczne i terminy (na dole).'],v:15},
  {i:'🧾',t:'Ulga w PIT',s:'wydatki do zeznania podatkowego',w:'Oznaczasz wydatki, które mogą obniżyć podatek (internet, darowizny, rehabilitacja, termomodernizacja). W styczniu masz gotowe zestawienie – osobno dla każdego z Was. To podpowiedź, nie porada podatkowa.',h:['W okienku wydatku stuknij „🧾 Do ulgi w PIT” i wybierz ulgę (pod spodem krótkie objaśnienie).','Zestawienie: 📌 Stałe → 💼 Pensje → Rok → „Pomocnik PIT”.'],v:15},
  {i:'🗣️',t:'Siri i skróty',s:'„Hej Siri, wydatek”',w:'Siri pyta o kwotę i notatkę, a aplikacja otwiera się z gotowym okienkiem – zostaje tylko „Zapisz”.',h:['⚙️ → „🗣️ Siri i skróty” → „Jak to ustawić” i krok po kroku utwórz skrót w aplikacji Skróty.','Przytrzymanie ikony aplikacji na ekranie telefonu też pokazuje skróty (Nowy wydatek, Na dziś).'],v:15}]},
 {s:'📊 Budżet i Analiza',items:[
  {i:'📊',t:'Plan i paski',s:'ile zostało w każdej pozycji',w:'Na każdą pozycję wpisujesz plan na miesiąc. Paski pokazują, ile już wydaliście i ile zostało. Wydatek bez planu jest „poza planem”.',h:['W Budżecie stuknij kategorię, żeby ją rozwinąć.','Wpisz kwotę w polu „Plan” przy pozycji.','„Skopiuj plan z poprzedniego miesiąca” na dole oszczędza pisanie, a „Wypełnij średnimi” podpowiada kwoty z ostatnich miesięcy.']},
  {i:'📅',t:'Wydatki roczne w planie',s:'OC, prezenty – same w planie miesiąca',w:'Gdy w danym miesiącu przypada wydatek roczny, jego kwota sama dolicza się do planu jego pozycji. Dzięki temu np. OC w marcu nie jest „poza planem”, a w kwietniu plan nie jest za duży (ta kwota się nie kopiuje). Zapłacony wcześniej – liczy się w miesiącu zapłaty.',h:['Wystarczy dodać wydatek w 📌 Stałe → 📅 Roczne (kwota, miesiąc, pozycja budżetu).','W Budżecie pod pozycją widać „📅 do planu doliczone: …”. Pole planu pokazuje tylko to, co wpisaliście sami.'],v:31},
  {i:'🗓️',t:'Zamknięcie miesiąca',s:'5 kroków dzień przed wypłatą – każde z Was osobno',w:'Raz w miesiącu warto sprawdzić, czy liczby w aplikacji są prawdziwe, i przygotować kolejny miesiąc. Każde z Was zamyka miesiąc samo, dzień przed swoją najwcześniejszą wypłatą – wtedy na koncie jest to, co naprawdę zostało z poprzedniej pensji. Kroki: 1) salda Twoich i wspólnych kont z bankiem, 2) co było ponad plan (wspólny), 3) nadwyżka na Twoich kontach bieżących (kaskada), 4) plan na nowy miesiąc (wspólny), 5) Twoje i wspólne cele.',h:['Dzień wypłaty aplikacja zna sama z pasków z ostatnich 3 miesięcy: rozpozna „koniec miesiąca”, a gdy dzień wypada w weekend – piątek przed nim. Bez pasków bierze dzień ze źródła dochodu, a bez źródła dochodu – od 1. dnia miesiąca.','Karta „🗓️ Zamknij …” na Budżecie i w 🔔 „Na dziś” przez ok. 10 dni, rano w dniu startu powiadomienie (tylko do Ciebie). Wypłata od 20. dnia → zamykasz bieżący miesiąc, wcześniej – poprzedni.','„Co było ponad plan” i „Plan” są wspólne – odhaczone przez jedno z Was są odhaczone u obojga. Przy planie podpowiadam średnią z 3 miesięcy (jeden drogi miesiąc nie podnosi planu na stałe).','Salda: „✓ Zgadza się” przy koncie albo „⚖️ Wyrównaj wszystkie salda naraz”. W każdej chwili: przycisk „🗓️ Zamknięcie miesiąca” na dole Budżetu.'],v:37},
  {i:'📊',t:'Plan a rzeczywistość',s:'czy plan pasuje do wydatków',w:'Po kilku miesiącach widać, które pozycje regularnie przekraczają plan (plan jest za mały albo wydatki za duże), a które są dużo poniżej. Jednym stuknięciem poprawisz plan od następnego miesiąca – wcześniejsze miesiące zostają bez zmian.',h:['📈 Analiza → Rok → karta „Plan a rzeczywistość”.','„Ustaw … od listopada” zmienia plan tej pozycji od następnego miesiąca.'],v:31},
  {i:'🙈',t:'Ukrywanie pozycji i kategorii',s:'np. spłacona pożyczka, kategoria na później',w:'Ukryta pozycja nie pokazuje się w Budżecie ani przy wpisywaniu, ale jej historia zostaje w Rejestrze i Analizie. Gdy w danym miesiącu ma jakiś wpis, Budżet i tak ją pokaże, żeby sumy się zgadzały. Pozycji z wpisami nie da się usunąć – tylko ukryć; pustą możesz usunąć.',h:['⚙️ → „Kategorie i pozycje budżetu” → stuknij pozycję → „🙈 Ukryj”.','Całą kategorię: stuknij jej nazwę → „Widoczność: Ukryta”.','Przywracanie: pod kategorią „🙈 Ukryte: … ↺ przywróć”.'],v:31},
  {i:'🔽',t:'Krótszy Budżet',s:'puste pozycje schowane',w:'Pozycje bez planu i bez wydatków nie zajmują miejsca, a kategorie zupełnie puste są w jednej linijce na dole.',h:['W kategorii stuknij „＋ N pustych pozycji”, żeby je pokazać (np. żeby wpisać plan).','Puste kategorie na dole – stuknij nazwę, żeby ją otworzyć.','Filtr „Bez planu” zawsze pokazuje wszystkie pozycje bez planu.'],v:17},
  {i:'👆',t:'Zmiana miesiąca palcem',s:'przesuń w lewo albo w prawo',w:'Zamiast strzałek ‹ › w nagłówku możesz przesunąć palcem po ekranie.',h:['Przesuń w lewo – następny miesiąc, w prawo – poprzedni. Działa w Budżecie, Rejestrze, Stałych i Analizie.'],v:17},
  {i:'📈',t:'Analiza',s:'wykresy, podsumowanie, Mati ↔ Wercia',w:'Podsumowanie miesiąca lub roku: na co idą pieniądze, porównanie z poprzednim okresem, kto ile wydaje, majątek w czasie, inflacja osobista, „Money Wrapped”.',h:['W Budżecie stuknij przycisk „📈 Analiza”.','Przełącz Miesiąc / Rok. „Podstawowa” pokazuje najważniejsze, „Pełna” – wszystkie wykresy.','Eksport do pliku CSV jest na dole.']},
  {i:'⏳',t:'Trwający miesiąc w Analizie',s:'porównanie do tego samego dnia',w:'Gdy miesiąc jeszcze trwa, porównuję go z poprzednim miesiącem do tego samego dnia – inaczej 10. dnia wszystko wyglądałoby na „dużo mniej niż ostatnio”. Ocenę „zmieściło się” i „wyraźnie mniej niż plan” pokazuję po końcu miesiąca.',h:['📈 Analiza → Miesiąc: pod kafelkami „⏳ Miesiąc jeszcze trwa – strzałki porównują z … do N. dnia”.'],v:35},
  {i:'🏪',t:'Gdzie wydajemy',s:'sklepy i miejsca z notatek',w:'Zestawienie miejsc z notatek wydatków (Biedronka, Lidl, Glovo…): ile wydaliście, ile razy i średnio za jednym razem. Bez opłat stałych.',h:['📈 Analiza → Pełna → „🏪 Gdzie wydajemy” (w miesiącu i w roku).','Im staranniej wpisujecie notatkę (ta sama nazwa sklepu), tym lepsze zestawienie.'],v:24},
  {i:'🖨️',t:'Podsumowanie roku',s:'jedna strona do PDF i mail 1 stycznia',w:'Cały rok na jednej stronie: przychody i wydatki, miesiąc po miesiącu, na co poszło najwięcej, ile odłożyliście, majątek na początku i na końcu roku, Mati ↔ Wercia, IKE/IKZE/PPK i ulgi do PIT.',h:['📈 Analiza → przełącz na „Rok” → „🖨️ Podsumowanie roku”.','„Zapisz jako PDF / drukuj” otwiera okno drukowania – na telefonie wybierz „Zapisz jako PDF” albo udostępnij.','1 stycznia automat wysyła podsumowanie poprzedniego roku mailem do Was obojga.'],v:19},
  {i:'🏷️',t:'Projekty',s:'auto, koty, wakacje – ile kosztują',w:'Projekt zbiera wydatki z różnych pozycji, np. wszystko o samochodzie albo o wakacjach. Przy aucie liczy też spalanie z tankowań.',h:['Na dole Budżetu: „🏷️ Projekty” → „+ Projekt”.','Przy wydatku wybierz projekt w okienku.']}]},
 {s:'🧾 Rejestr i szukanie',items:[
  {i:'🧾',t:'Rejestr',s:'wszystkie wpisy z filtrami',w:'Lista wszystkich wpisów miesiąca, roku albo całości – każdy w dwóch linijkach: pozycja, a pod nią notatka · konto · osoba. Kategorię widać po kolorowej ikonce, przy każdym dniu suma wydatków.',h:['Wyszukiwarka u góry szuka po notatce, pozycji, koncie i kwocie – np. „>200” albo „100-300”.','Obok okresu (Ten miesiąc / Cały rok / Wszystko) jest „⚙️ Filtry”: rodzaj, osoba, konto, kategoria. Liczba w nawiasie mówi, ile filtrów działa. „✕ Wyczyść filtry” wraca do wszystkiego.'],v:35},
  {i:'✋',t:'Przytrzymanie wpisu',s:'Duplikuj, Zwrot, Usuń',w:'Szybkie akcje bez otwierania wpisu.',h:['Przytrzymaj wpis w Rejestrze palcem przez pół sekundy.','📋 Duplikuj – to samo jeszcze raz (np. ta sama kawa), z dzisiejszą datą do zmiany.','↩️ Zwrot, ✏️ Otwórz, 🗑️ Usuń (z „Cofnij” w dymku).'],v:17},
  {i:'🔍',t:'Szukaj wszędzie',s:'lupa w nagłówku',w:'Jedno wyszukiwanie po wpisach, pozycjach budżetu, kontach, instrumentach i opłatach stałych.',h:['Stuknij 🔍 na górze i wpisz kilka liter albo kwotę.','Stuknij wynik – przeniosę Cię we właściwe miejsce.'],v:17},
  {i:'🗑️',t:'Ostatnio usunięte',s:'przywróć usunięty wpis',w:'Usunięty wpis nie znika na zawsze. Przez 60 dni widać go na liście i można go jednym stuknięciem wstawić z powrotem – razem z jego zwrotami, PPK i odsetkami.',h:['⚙️ → „🗑️ Ostatnio usunięte” → „↩️ Przywróć”.','Po przywróceniu przez chwilę jest jeszcze „Cofnij”.'],v:23},
  {i:'🕑',t:'Kto co zmienił',s:'dodał, zmienił, usunął',w:'Przy każdym wpisie widać, kto go dodał i kto zmienił – przydaje się, gdy oboje wpisujecie.',h:['Otwórz wpis – na dole okienka jest „dodał / zmieniła”.','Lista ostatnich zmian: ⚙️ → „🕑 Ostatnie zmiany”.'],v:15},
  {i:'🧹',t:'Strażnik porządku',s:'duplikaty, brak pozycji, ujemne saldo',w:'Sam wyłapuje możliwe pomyłki: podwójne wpisy, wpisy bez pozycji, ujemne saldo konta bieżącego, pasek pensji, który się nie zgadza.',h:['Podpowiedzi są w 🔔 „Na dziś”.','„To nie błąd” ukrywa daną podpowiedź na stałe.'],v:13}]},
 {s:'📌 Stałe',items:[
  {i:'📌',t:'Opłaty i przychody stałe',s:'odhaczasz co miesiąc',w:'Czynsz, prąd, abonamenty i stałe przychody (np. najem) wpisujesz raz. Co miesiąc odhaczasz je jednym stuknięciem, a wpis sam trafia do Rejestru. O terminach przypominam w 🔔 „Na dziś” i powiadomieniem.',h:['📌 Stałe → „+ Opłata” albo „+ Przychód”.','Stuknij kwadracik, gdy zapłacone – drugi raz, żeby odznaczyć.','Przy najmie wybierz „🏠 Najem” – przypomnę o ryczałcie.']},
  {i:'🔁',t:'Stałe przelewy',s:'oszczędności, zrzutka na wspólne',w:'Przelew co miesiąc z konta na konto: na oszczędności, na konto wspólne, na konto drugiej osoby albo na subkonto. Odhaczasz go jak opłatę. Jako „odłożone” liczą się tylko przelewy na oszczędności i inwestycje.',h:['📌 Stałe → „🔁 Stałe przelewy” → „+ Przelew”.','Gdy ten sam przelew (te same konta, podobna kwota) jest co miesiąc od 3 miesięcy, zapytam „Dodać do stałych przelewów?”.'],v:37},
  {i:'⚠️',t:'Nie starczy na rachunki',s:'ostrzeżenie przed terminem opłaty',w:'Sprawdzam każde konto bieżące do końca miesiąca: odejmuję nieodhaczone opłaty stałe, stałe przelewy i raty z 📌 Stałe, doliczam to, co wpłynie wcześniej (pensję – kwotą z ostatniego paska, przychody stałe, stałe przelewy na to konto). Gdy na którąś opłatę zabraknie – ostrzeżenie w 🔔 „Na dziś”. Liczę tylko rzeczy stałe, nie zakupy.',h:['„Przelej” otwiera przelew na to konto z brakującą kwotą. „Wiem” chowa ostrzeżenie na ten miesiąc.','Powiadomienie: pierwszego dnia problemu i dzień przed opłatą – do właściciela konta, przy koncie wspólnym do obojga.'],v:37},
  {i:'🔗',t:'Jeden rachunek – jeden wpis',s:'wpis z ＋ a opłata stała',w:'Opłatę stałą możesz zapłacić na dwa sposoby: odhaczyć w 📌 Stałe albo wpisać przez ＋. Aplikacja pilnuje, żeby ten sam rachunek nie policzył się dwa razy: wpis z ＋ podobny do nieodhaczonej opłaty (ta sama pozycja i podobna kwota albo nazwa w notatce) – pyta, czy go odhaczyć; przy odhaczaniu, gdy taki wpis już jest – proponuje połączenie. Tak samo przy wydatkach rocznych (OC, ubezpieczenie).',h:['Zapisujesz wpis → „To … z opłat stałych?” → „Tak, odhacz”.','📌 Stałe → kwadracik przy opłacie z „💡 jest podobny wpis” → „Połącz z tym wpisem”.','Gdy to naprawdę coś innego: „Nie, to coś innego” albo „To inny – dodaj nowy wpis”.'],v:34},
  {i:'📌',t:'Plan a opłaty stałe',s:'plan nie mniejszy niż rachunki',w:'Jeśli plan pozycji jest niższy niż suma jej opłat stałych (np. czynsz wzrósł, a plan skopiował się ze starego miesiąca), pozycja byłaby co miesiąc „ponad plan”. Budżet to pokazuje i jednym przyciskiem podnosi plan.',h:['Budżet → karta „📌 Plan niższy niż opłaty stałe” → „Podnieś plan do opłat stałych”.','Pod pozycją widać „📌 opłaty stałe w tej pozycji: …”.'],v:34},
  {i:'📄',t:'Koniec umowy',s:'przypomnienie 2 miesiące wcześniej',w:'Przy opłacie stałej (internet, telefon, ubezpieczenie) wpisz, do kiedy masz umowę. 2 miesiące przed końcem przypomnę w „Na dziś”, żeby porównać oferty albo negocjować cenę.',h:['📌 Stałe → stuknij nazwę opłaty → „📄 Umowa do”.','Na liście opłat widać „📄 umowa do …”. W „Na dziś” przycisk „Załatwione” chowa przypomnienie; przy nowej umowie wpisz nową datę.'],v:24},
  {i:'👥',t:'Opłaty według osoby',s:'Wszystkie · Mati · Wercia · Wspólne',w:'W 📌 Opłatach możesz zobaczyć tylko opłaty, przychody i przelewy stałe jednej osoby. Czyje są, wynika z konta, z którego idą (konto wspólne = wspólne). Gdy jest inaczej – np. telefon Matiego płacony ze wspólnego konta – ustaw w edycji „👥 Dotyczy”.',h:['📌 Stałe → 📌 Opłaty → przełącznik na górze.','Telefon zapamiętuje ostatni wybór.'],v:42},
  {i:'🌸',t:'Kwiatki Werci',s:'ozdoby w różowym kolorze, tylko na telefonie Werci',w:'Gdy na telefonie korzysta Wercia i ma różowy kolor, aplikacja dostaje kwiatki: przy powitaniu, miesiącu, zakładkach, w kafelkach ustawień, okienku wpisu, Analizie i pustych ekranach. Paski celów rosną jak łodyżki i zakwitają na 100%, a zamiast konfetti spadają płatki wiśni. To tylko wygląd – dane i obliczenia bez zmian.',h:['⚙️ → 📱 Ten telefon → 🎨 Wygląd → różowy.'],v:45},
  {i:'⚙️',t:'Ustawienia – kafelki',s:'6 części, każda na osobnym ekranie',w:'🏦 Konta – dodawanie, zmiana, oprocentowanie, archiwum. 🗂️ Kategorie i drobne – pozycje budżetu i 🪙 drobne. 📱 Ten telefon – 🎨 wygląd, 🙈 tryb dyskretny, 🐾 kotki, kto korzysta, urodziny. 🛡️ Bezpieczeństwo – kopia danych, wczytanie kopii, ostatnio usunięte, ostatnie zmiany, wylogowanie. 🤖 Automaty – 🔔 powiadomienia, 📧 maile, automat, Siri. 📖 Pomoc – ten przewodnik, pierwsze kroki, wersja demo.',h:['⚙️ w prawym górnym rogu → stuknij kafelek.','„‹ Ustawienia” albo ⚙️ wraca do kafelków.'],v:44},
  {i:'🔔',t:'Każde ma swoje przypomnienia',s:'swoje i wspólne – bez spraw drugiej osoby',w:'Na Budżecie („Do odhaczenia”), w 🔔 „Na dziś”, w dymku kotków i w powiadomieniach widzisz tylko swoje sprawy i wspólne. Opłaty drugiej osoby nie przeszkadzają. Czyje to jest: „👥 Dotyczy” albo właściciel konta. Wydatki roczne i przypomnienia bez „Dotyczy” są wspólne. Kopia danych, automat i limity IKE/IKZE – tylko u Matiego.',h:['Ustaw „👥 Dotyczy” w opłacie stałej, wydatku rocznym albo przypomnieniu.','Cudze opłaty nadal są w 📌 Stałe → przełącznik osoby.'],v:43},
  {i:'🙀',t:'Cudze konto',s:'kotki pytają przy wpisie',w:'Gdy wpisujesz wydatek, przychód albo przelew z konta drugiej osoby, kotki pytają, czy na pewno – żeby salda się zgadzały. Po „Tak, wiem” do końca dnia nie pytają o to konto. Konta wspólne i przelewy NA konto drugiej osoby nie wywołują pytania. Osoba telefonu jest przypisana na stałe do loginu (⚙️ → „Kto korzysta”).',h:['„Tak, wiem, co robię” – zapisuje.','„Zmień konto” – wraca do okienka, nic się nie zapisuje.'],v:42},
  {i:'📆',t:'Opłaty stałe w roku',s:'ile kosztują rocznie',w:'Pod listą opłat stałych: ile kosztują w roku i miesięcznie, w tym subskrypcje (z nazwami) i wydatki roczne.',h:['📌 Stałe → „📆 Opłaty stałe w roku”.'],v:24},
  {i:'💡',t:'Podpowiedź stałej opłaty',s:'„Dodać do opłat stałych?”',w:'Gdy coś płacisz co miesiąc (ta sama notatka, podobna kwota, 3 miesiące z rzędu), a nie ma tego w Stałych – zapytam, czy to dodać.',h:['Podpowiedź pojawi się w 📌 Stałe i w 🔔 „Na dziś”.','„Dodaj” otwiera gotowy formularz, „Nie, dzięki” – więcej nie zapytam.'],v:16},
  {i:'🧮',t:'Pasek z kwoty netto',s:'gdy nie masz jeszcze paska',w:'Wystarczy kwota, która wpłynęła na konto. Aplikacja policzy orientacyjnie brutto, ZUS, zdrowotną, podatek i PPK – tak, żeby rachunek paska się zgadzał. Gdy dostaniesz prawdziwy pasek, przepiszesz z niego brutto.',h:['📌 Stałe → 💼 Pensje → „+ Wpisz pasek” → „🧮 Podpowiedz z netto”.','Wpisz kwotę z aplikacji banku; przy PPK wybierz, czy było w tej wypłacie.','Potrącenia (np. Multisport) doliczę – są w pasku w „Potrącenia”.','„✓ To już kwoty z paska” zdejmuje oznaczenie szacunku.'],v:29},
  {i:'🎓',t:'Ulga dla młodych',s:'do 26 lat bez podatku od pensji',w:'Do dnia 26. urodzin pensja z umowy o pracę i umowy zlecenia (razem z wpłatą PPK pracodawcy) jest zwolniona z podatku – do 85 528 zł w roku, ze wszystkich umów razem. ZUS i składka zdrowotna są jak zwykle. Aplikacja liczy to sama z daty urodzenia: w pasku widać, ile jest bez podatku i ile limitu zostało. Miesiąc przed 26. urodzinami przypomnę, że kolejne wypłaty będą niższe.',h:['Data urodzenia: Bailey i Ivo pytają o nią przy starcie, zmienisz ją w ⚙️ → „Kto korzysta z tego telefonu?”.','💼 Pensje → pasek → „Podpowiedz z brutto” albo „z netto” – podatek policzy się z ulgą.','💼 Pensje → Rok: „w tym zwolniony (ulga dla młodych)” do porównania z PIT-11.'],v:33},
  {i:'✂️',t:'Potrącenia z pensji',s:'ubezpieczenie grupowe, Multisport',w:'To, co pracodawca potrąca od razu z wypłaty, nie wpływa na konto, ale jest Waszym wydatkiem. Wpisujesz to raz przy źródle dochodu – w każdym nowym pasku pojawi się samo i trafi do budżetu w wybranej pozycji.',h:['💼 Pensje → „+ Źródło dochodu” (albo ⋯ przy źródle) → trzecie okienko „✂️ Potrącenia z pensji”.','Zmiana kwoty w danym miesiącu: w pasku, w „Potrącenia”. Kolejny pasek weźmie kwoty z poprzedniego.'],v:29},
  {i:'➕',t:'Inne przychody',s:'sprzedaż rzeczy, premia, zwrot PIT, najem',w:'Przychody spoza pasków wpisujesz jak zwykły przychód. W 💼 Pensje widać je wszystkie pod pensjami, razem z sumą miesiąca. Stały przychód (np. najem) dodasz w 📌 Stałe → „+ Przychód” i będziesz go odhaczać co miesiąc.',h:['💼 Pensje → „+ Inny przychód” (albo ＋ → Przychód).','Najem: 📌 Stałe → Opłaty → „+ Przychód”.'],v:29},
  {i:'🏠',t:'Najem i ryczałt',s:'przypomnienie o podatku od najmu',w:'Przy przychodzie stałym z najmu przypomnę o ryczałcie (8,5% przychodu, do 100 000 zł rocznie) – do 20. dnia po miesiącu albo po kwartale – z wyliczoną kwotą, a w lutym o PIT-28.',h:['📌 Stałe → „+ Przychód” (albo stuknij istniejący) → „🏠 Najem – przypominać o ryczałcie?” → co miesiąc albo co kwartał.','W „Na dziś” stuknij „✓ Zapłacone”, gdy podatek pójdzie.'],v:32},
  {i:'🧾',t:'PIT co roku',s:'od 1 marca do 30 kwietnia',w:'Od 1 marca w „Na dziś” przypominam o zeznaniu za poprzedni rok – każdemu z Was osobno – z przyciskiem do zestawienia ulg i IKZE. Powiadomienie przychodzi 1 marca, 1 i 20 kwietnia.',h:['W „Na dziś” stuknij „Zestawienie”, a po złożeniu „✓ Złożone”.'],v:32},
  {i:'💼',t:'Pensje i pasek',s:'brutto, netto, PPK, PIT-11',w:'Źródła dochodu każdego z Was (umowa o pracę, zlecenie, dzieło, JDG). Co miesiąc wpisujesz pasek: przychód w budżecie, wpłaty PPK i potrącenia liczą się same, a widok roku pomaga przy PIT.',h:['📌 Stałe → 💼 Pensje → „+ Źródło dochodu”.','Co miesiąc „Wpisz pasek” – „Skopiuj z poprzedniego miesiąca” albo „Podpowiedz z brutto” przyspieszają.','„Rok” – suma do porównania z PIT-11 i „Pomocnik PIT”.']},
  {i:'📅',t:'Roczne i terminy',s:'OC, ubezpieczenie, prezenty – koperty i przypomnienia',w:'Jedno miejsce na wszystko, co wraca co rok albo co kilka miesięcy. Z kwotą – aplikacja liczy, ile odkładać co miesiąc na wspólne subkonto, i dolicza tę kwotę do planu w miesiącu płatności. Bez kwoty – tylko przypomina. Zawsze ok. 2 tygodnie przed terminem (także gdy koperta jest już pełna).',h:['📌 Stałe → 📅 Roczne i terminy → „+ Dodaj” → wybierz gotowe (OC, przegląd, opony, szczepienie kotów…) albo wpisz własne.','Wpisz kwotę, najbliższy termin i co ile się powtarza.','Na górze Budżetu widać, ile w tym miesiącu jeszcze odłożyć. Po zapłacie stuknij „✓ Zapłacone”.'],v:32},
  {i:'🔔',t:'Terminy bez odkładania',s:'opony, serwis co X km, szczepienie kotów',w:'Rzeczy co jakiś czas, na które nie odkładacie osobno – po dacie albo po kilometrach auta. Przypomnę ok. 2 tygodnie przed terminem.',h:['📌 Stałe → 📅 Roczne i terminy → „+ Dodaj” → wybierz gotowe albo wpisz własne, bez kwoty.','„✓ Zrobione” przesuwa termin na następny raz. W „Edytuj” możesz dopisać kwotę – wtedy będę liczyć odkładanie.'],v:32}]},
 {s:'💰 Majątek',items:[
  {i:'💰',t:'Oprocentowanie konta',s:'odsetki, promocja, podatek Belki',w:'Aplikacja liczy odsetki konta oszczędnościowego dzień po dniu od salda (saldo × stawka ÷ 365) – także przy promocji z limitem kwoty i po zmianie stawki. Odejmuje podatek Belki 19% (bez podatku przy IKE, IKZE i OKI; przy banku zagranicznym – „Rozliczam sam”, a w marcu przypomni o PIT-38). Odsetki to zysk, nie liczą się do „odłożonych”.',h:['💰 Majątek → Oszczędności → przy koncie „💰 Oprocentowanie” (albo ⚙️ → Konta → 💰).','Wpisz stawkę, ewentualnie promocję (do kiedy, do jakiej kwoty) i kiedy bank dopisuje odsetki.','W dniu dopisania „Na dziś” pokaże szacunek – „Wpisz” i popraw kwotę z wyciągu, jeśli się różni.','Przy zmianie stawki wpisz nową i datę „od kiedy” – wcześniejsze miesiące liczą się po starej.'],v:40},
  {i:'🐷',t:'Odłożone',s:'ile naprawdę odkładacie',w:'Odłożone to pieniądze przelane na konta oszczędnościowe i inwestycyjne (także wpłaty PPK) minus to, co z nich wypłaciliście. Zmiana kursów inwestycji się nie liczy – pokazuję ją osobno jako „inwestycje zarobiły / straciły”. Dzięki temu cel miesięczny i podsumowania mówią prawdę także, gdy giełda rośnie albo spada.',h:['Budżet – wiersz „🐷 Odłożone w tym miesiącu” pod kafelkami (stuknij, żeby przejść do Oszczędności).','💰 Majątek → Oszczędności → „Ile odłożyliście” – miesiąc, rok i cel miesięczny.','Analiza – kafelek „Odłożone” (procent przychodów) i „zostaje z przychodów”.'],v:30},
  {i:'🐷',t:'Oszczędności',s:'Razem / każde z Was / Wspólne',w:'Konta oszczędnościowe, poduszka bezpieczeństwa, IKE, IKZE, PPK i inwestycje w jednym miejscu, z podziałem na osoby.',h:['💰 Majątek → „🐷 Oszczędności”.','„🐷 Odłóż” robi przelew na oszczędności, „📈 Aktualizuj wartości” wpisuje wyceny z aplikacji brokerów.','💧 Kaskada nadwyżek (zakładka osoby i zamknięcie miesiąca): dzień przed wypłatą proponuje przelać to, co zostało na koncie bieżącym ponad zapas (250 zł, ⚙️ do zmiany) i opłaty stałe przed wypłatą. Pensja, która już wpłynęła, nie jest nadwyżką. W inne dni pokazuje, kiedy policzy.'],v:37},
  {i:'🧭',t:'Która koperta do czego',s:'cel, roczne, odkładanie na spłatę, projekt',w:'Cztery sposoby na pieniądze „na coś”. 🎯 Cel – jednorazowe marzenie (wakacje, nowe auto): przydzielacie część oszczędności. 📅 Roczne – to, co wraca co rok (OC, prezenty): prawdziwe pieniądze na wspólnym subkoncie. 💰 Odkładanie na spłatę – gdy chcecie spłacić pożyczkę całą naraz. 🏷️ Projekt – nic nie odkłada, liczy, ile coś kosztuje (auto, koty, remont).',h:['Co rok → 📅 Roczne i terminy.','Jednorazowe marzenie → 🎯 Cel w Oszczędnościach.','Spłata pożyczki naraz → przy pożyczce w 🔻 My winni.','„Ile to kosztowało” → 🏷️ Projekt.'],v:32},
  {i:'🎯',t:'Cele-koperty',s:'wakacje, auto, remont',w:'Przydzielacie część oszczędności do celu i widzicie, ile brakuje i ile odkładać miesięcznie do terminu. Konto „Poduszka…” nie liczy się do puli na cele, a karta poduszki odejmuje pieniądze przydzielone do celów – ta sama złotówka nie jest i poduszką, i wakacjami.',h:['💰 Majątek → Oszczędności → „+ Cel”.'],v:37},
  {i:'🛡️',t:'IKE, IKZE, PPK – limity',s:'ile jeszcze można wpłacić',w:'Pilnuję rocznych limitów wpłat. W grudniu przypomnę o IKZE (ulga w PIT), a automat sam znajduje limity na nowy rok i pyta, czy je wpisać.',h:['Karta „Limity” w Oszczędnościach. „✎ Limity” – poprawka ręczna.']},
  {i:'📈',t:'Instrumenty',s:'ETF, akcje, złoto, krypto, lokaty',w:'Na koncie inwestycyjnym zapisujesz zakupy i sprzedaże. Aplikacja liczy wartość, zysk i kwotę „na rękę” po podatku Belki (na IKE/IKZE/PPK bez podatku).',h:['Konto inwestycyjne → „Instrumenty” → „+ Dodaj instrument”.','„Symbol dla automatu” (np. IWDA.UK) – wtedy cenę pobiera automat.','„⚖️ Zapisz wycenę” przenosi wynik do salda konta.']},
  {i:'🏛️',t:'Obligacje skarbowe',s:'EDO, COI, ROS, ROD – liczą się same',w:'Każdy rok odsetkowy liczę z inflacji GUS sprzed 2 miesięcy plus marża – tak jak Ministerstwo Finansów. Przy nowym zakupie podpowiadam oprocentowanie serii w sprzedaży.',h:['Instrument → rodzaj „Obligacje skarbowe”, wpisz liczbę obligacji.','„📅 Oprocentowanie” pokazuje każdy rok i skąd się wziął; rok, który trwa, możesz poprawić według tabeli odsetkowej.','Miesiąc przed wykupem przypomnę w „Na dziś”.'],v:16},
  {i:'🧺',t:'Fundusze PPK i TFI',s:'wybierz fundusz, wpisz jednostki',w:'Automat codziennie pobiera wartość jednostki funduszu, więc PPK wycenia się samo.',h:['Konto PPK → „+ Dodaj instrument” → „Fundusz TFI / PPK” → wybierz fundusz z listy (pogrupowane według instytucji).','Wpisz liczbę jednostek z aplikacji PPK. Później „✎ Liczba jednostek” – raz na jakiś czas wystarczy.'],v:16},
  {i:'👛',t:'Konta i salda',s:'wszystkie konta, wyrównanie',w:'Salda wszystkich kont, z podziałem na osoby i rodzaje („Czyj majątek”). Gdy saldo w aplikacji różni się od banku, wyrównujecie wszystkie salda naraz – na jednym ekranie (pojedynczych kont nie poprawia się osobno).',h:['💰 Majątek → „👛 Konta” → „🏦 Salda”. Kafelek „Na kontach ›” na Budżecie też tu prowadzi.','„⚖️ Wyrównaj wszystkie salda naraz” – wpisz salda z banku, różnice zapiszę jako przelewy albo wyrównania. Ten sam przycisk jest w zamknięciu miesiąca.'],v:37},
  {i:'🔻',t:'My winni i Nam winni',s:'kredyty, pożyczki',w:'Zobowiązania (kredyt, raty, pożyczka od rodziny) i pieniądze pożyczone innym. Stan kont się przez nie nie zmienia – w 👛 Konta widać je osobno („do spłaty”, „pożyczone innym”).',h:['💰 Majątek → Konta → „🔻 My winni” albo „🔺 Nam winni” → „+”.','Ratę wpisujesz jak wydatek z wybranym zobowiązaniem – „pozostało” zmniejsza się samo.']},
  {i:'🧮',t:'Raty i odsetki',s:'podpowiedź raty, koniec spłaty',w:'Z oprocentowania nominalnego (nie RRSO) liczę ratę na ten miesiąc, jej część odsetkową, koniec spłaty i odsetki do końca. To podpowiedź – bank liczy co do dnia, więc kwota może się różnić o grosze.',h:['🔻 My winni → Edytuj → „Oprocentowanie nominalne” i „Raty: równe / malejące”. Rata z umowy (jeśli ją wpiszesz) ma pierwszeństwo przed wyliczoną.','„+ Rata” wpisuje podpowiedź – zmień ją, jeśli bank pobrał inną kwotę.','Bez oprocentowania: to, co zostało ÷ miesiące do „Do kiedy”.','Z każdej raty dług zmniejsza się tylko o część kapitałową. Cała rata zostaje wydatkiem w Budżecie.','W dniu raty przypomnę o niej w 🔔 „Na dziś” (chyba że ta rata jest już w 📌 Stałe).'],v:21},
  {i:'💰',t:'Odkładanie na spłatę pożyczki',s:'zbieram i spłacam całość naraz',w:'Co miesiąc odkładasz na konto, a przy pożyczce widzisz, ile już uzbierałeś. Na jedno konto możesz zbierać na kilka pożyczek – każda ma swój licznik. Spłata całości nie liczy się w Budżecie, tylko odsetki.',h:['🔻 My winni → Edytuj pożyczkę → „💰 Zbieram na spłatę całości na koncie”.','„💰 Odłóż” na karcie pożyczki albo zwykły przelew na to konto – w przelewie wpisz, ile na którą pożyczkę (reszta zostaje wolna).','Stały przelew (📌 Stałe) też możesz przypisać do pożyczki – po odhaczeniu odłoży się sam.','„↑ Weź z odłożonych”, gdy potrzebujesz tych pieniędzy na coś innego.','„✅ Spłać całość” – wpisz kapitał i odsetki z banku. Odłożone pieniądze zużyją się same.'],v:20}]},
 {s:'🤖 Automaty',items:[
  {i:'🔔',t:'Na dziś',s:'dzwonek w nagłówku',w:'Wszystko, co dziś czeka: opłaty po terminie, paski pensji, przypomnienia, końce gwarancji, wykupy obligacji, kopia danych.',h:['Stuknij 🔔 – licznik pokazuje, ile spraw czeka.','Przycisk przy sprawie przenosi tam, gdzie trzeba ją załatwić.']},
  {i:'📲',t:'Powiadomienia na telefon',s:'rano 7:30 i wieczorem 20:00',w:'Prawdziwe powiadomienia, także gdy aplikacja jest zamknięta: rano „Na dziś”, wieczorem przypomnienie, gdy nic nie wpisano.',h:['⚙️ → „🔔 Powiadomienia” → „Włącz” – każde z Was na swoim telefonie.'],v:13},
  {i:'📧',t:'Maile',s:'kopia i podsumowanie miesiąca',w:'W pierwszą niedzielę miesiąca kopia zapasowa przychodzi mailem do Matiego, a 1. dnia miesiąca oboje dostajecie podsumowanie poprzedniego miesiąca.',h:['Nic nie trzeba robić – automat działa sam. Kopię wczytasz w ⚙️ → „Wczytaj kopię”.'],v:14},
  {i:'💱',t:'Kursy, ceny, inflacja',s:'automat w dni robocze',w:'Codziennie po 18:00 automat pobiera kursy walut NBP, stopę NBP, inflację GUS, ceny instrumentów i funduszy oraz ofertę obligacji. Na koniec miesiąca sam zapisuje wycenę kont z instrumentami.',h:['Stan automatu: ⚙️ → „🤖 Automat (GitHub)”.','Wpis „Wycena instrumentów (automat)” możesz usunąć w Rejestrze jak każdy inny.'],v:16}]},
 {s:'⚙️ Ustawienia',items:[
  {i:'🎨',t:'Wygląd',s:'kolor i wielkość tekstu',w:'Każdy telefon ma swój kolor akcentu (Wercia różowy, Mati miętowy – można zmienić) i wielkość tekstu A / A+ / A++.',h:['⚙️ → „🎨 Wygląd” – stuknij kółko koloru i wielkość tekstu.'],v:17},
  {i:'🙈',t:'Tryb dyskretny',s:'kwoty jako „•••”',w:'Gdy pokazujecie komuś telefon albo otwieracie aplikację przy ludziach: wszystkie kwoty zamieniają się w „•••”. Procenty, paski i wykresy zostają. Dotyczy tylko tego telefonu.',h:['⚙️ → „🎨 Wygląd” → „🙈 Ukryte”.','Szybciej: przytrzymaj nazwę miesiąca w nagłówku (ok. pół sekundy) – włącza i wyłącza.','Na górze każdego ekranu jest wtedy pasek „Pokaż kwoty”.'],v:26},
  {i:'🚫',t:'Bez przybliżania',s:'podwójne stuknięcie',w:'Podwójne stuknięcie nie przybliża już ekranu (przyciski działają normalnie, także szybkie „+ +”). Przybliżyć można dwoma palcami.',h:['Nic nie trzeba ustawiać – działa samo.'],v:23},
  {i:'🎂',t:'Urodziny',s:'życzenia od Bailey i Ivo',w:'W dniu Waszych urodzin kotki składają życzenia na Budżecie (z konfetti) i rano w powiadomieniu, a drugiej osobie przypominają o życzeniach.',h:['Datę urodzenia zapisujesz raz – kotki pytają o nią przy starcie aplikacji.','Zmiana: ⚙️ → „Ten telefon” → „Kto korzysta z tego telefonu?” → 🎂 Zmień.'],v:33},
  {i:'📚',t:'Ciekawostka dnia',s:'„Rozumiem, kociaki”',w:'Pod uwagą kotków (opłata po terminie, przekroczony plan, blisko limitu) jest przycisk „Rozumiem, kociaki 🐾”. Uwaga znika do jutra na tym telefonie, a w jej miejscu pojawia się ciekawostka dnia o budżecie, oszczędzaniu lub inwestowaniu – 366 różnych, jedna na każdy dzień roku, na obu telefonach ta sama. Po południu kotki pokazują ją same. W święta i urodziny są życzenia.',h:['Budżet → dymek kotków → „Rozumiem, kociaki 🐾”.','Gdy sytuacja się zmieni (np. kolejna opłata po terminie), uwaga wróci.'],v:39},
  {i:'🐾',t:'Bailey i Ivo',s:'dużo, mało albo wcale',w:'Kotki podpowiadają, świętują i żartują. Możesz zostawić tylko ważne komunikaty albo je wyłączyć.',h:['⚙️ → „🐾 Bailey i Ivo” → Dużo / Mało / Wyłączone.','„Pokaż pierwsze kroki” – krótka wycieczka po aplikacji.']},
  {i:'💾',t:'Kopia danych',s:'plik z całym budżetem',w:'Plik z wszystkimi danymi – na wszelki wypadek: wpisy, konta, plany, paski, cele, a także ustawienia (kaskada, schowane podpowiedzi, koperty roczne, inflacja, limity, urodziny, zamknięcia miesięcy). Kopia z maila zawiera to samo. Tym samym przyciskiem wczytasz kopię lub listę transakcji.',h:['⚙️ → „Pobierz kopię” i zapisz plik w Plikach / na Dysku.','„Wczytaj kopię” przyjmuje plik .json i .json.gz z maila.'],v:38},
  {i:'🧪',t:'Wersja demonstracyjna',s:'pokaż komuś aplikację',w:'Osobna wersja z przykładowymi danymi – bez Waszych danych i bez logowania. Każdy gość ma swoją kopię w swojej przeglądarce.',h:['⚙️ → „🧪 Pokaż komuś aplikację” → „📤 Wyślij link”.'],v:18}]}];
